27	test('commentOnly sees through comments, and only in languages it models', () => {
28	  const before = 'export const a = 1; // one\n\n/* block */\nexport const b = 2;\n';
29	  const after = '// a different comment\nexport const a = 1;\nexport const b = 2;\n';
30	  assert.equal(commentOnly('engine/x.mjs', before, after), true);
31	  assert.equal(commentOnly('engine/x.mjs', before, after.replace('= 2', '= 3')), false);
32	  // A `#`-comment language is not modeled: its comment-only change reads as code,
