48	// THE WORK LIST IS A MARKED ISSUE (tasks-dispatch DESIGN §16.1, §16.12). The
49	// enforcer marks each work-list issue `task:origin:ad-hoc` and names the member
50	// task in the body's `Task:` field, so the member's ordinary hourly scheduler run
51	// adopts it: the issue becomes the work item, and the run that drains it plays out
52	// on the issue itself. That retires the old fan-out's second half — a
53	// `wake: <task>` dispatch into every member — leaving the dispatch as latency
54	// sugar rather than the delivery.
55	export const MARK = 'task:origin:ad-hoc';
56	export const MEMBER_TASK_ID = 'claudinite-lifecycle/adopt-requested-packs';

